-- Legacy billing database (PostgreSQL 11 era). Generated, deterministic.
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;

CREATE TABLE customers (
    id          integer PRIMARY KEY,
    name        text NOT NULL,
    email       text,
    country     char(2) NOT NULL,
    created_at  timestamp without time zone NOT NULL  -- America/New_York wall-clock time
);
CREATE TABLE invoices (
    id          integer PRIMARY KEY,
    customer_id integer NOT NULL REFERENCES customers(id),
    amount      numeric(12,2) NOT NULL,
    currency    char(3) NOT NULL,
    status      text NOT NULL,
    issued_at   timestamp without time zone NOT NULL  -- America/New_York wall-clock time
);
CREATE SEQUENCE customers_id_seq;
CREATE SEQUENCE invoices_id_seq;
CREATE INDEX invoices_customer_idx ON invoices(customer_id);
CREATE INDEX invoices_issued_idx ON invoices(issued_at);

COPY customers (id, name, email, country, created_at) FROM stdin;
